        default: fatalError("PhotoOutcome: no variant \(t)")
        }
    }

    public var json: String {
        switch self {
        case let .ok(value): return "{\"Ok\":" + J.obj(["\"value\":" + value.json]) + "}"
        case let .err(why): return "{\"Err\":" + J.obj(["\"why\":" + J.q(why)]) + "}"
